package cn.kejian.app;
import java.time.*;import java.util.*;
public final class CoursePlanTest {
 static int count;static void check(boolean ok){if(!ok)throw new AssertionError("Check "+(count+1));count++;}
 static long at(String t){return LocalDateTime.parse(t).atZone(ZoneId.of("Asia/Shanghai")).toInstant().toEpochMilli();}
 static CoursePlan.Plan plan(List<CoursePlan.Course> rows,Map<String,String> rules,String t){return CoursePlan.calculate(rows,rules,at(t),ZoneId.of("Asia/Shanghai"));}
 public static void main(String[] args){Map<String,String> rules=new HashMap<>();List<CoursePlan.Course> rows=new ArrayList<>();rows.add(new CoursePlan.Course("2026-10-13","A","Room","08:00","09:00"));rows.add(new CoursePlan.Course("2026-10-13","B","","09:00","10:00"));rows.add(new CoursePlan.Course("2026-10-14","C","","08:00","09:00"));
 CoursePlan.Plan p=plan(rows,rules,"2026-10-13T07:59:00");check(p.current==null);check(p.next.name.equals("A"));check(p.boundary==at("2026-10-13T08:00:00"));p=plan(rows,rules,"2026-10-13T08:00:00");check(p.current.name.equals("A"));check(p.next.name.equals("B"));check(p.boundary==at("2026-10-13T09:00:00"));check(p.text().contains("Room"));check(!p.text().contains("null"));p=plan(rows,rules,"2026-10-13T09:00:00");check(p.current.name.equals("B"));check(p.next.name.equals("C"));p=plan(rows,rules,"2026-10-13T10:00:00");check(p.current==null);check(p.next.name.equals("C"));check(p.boundary==at("2026-10-14T00:00:00"));p=plan(rows,rules,"2026-10-14T08:00:00");check(p.current.name.equals("C"));check(p.next==null);p=plan(Collections.emptyList(),rules,"2026-10-13T08:30:00");check(p.empty);check(p.current==null&&p.next==null);
 rules.put("2026-10-14","2026-10-13");p=plan(rows,rules,"2026-10-14T08:30:00");check(p.current.name.equals("A"));check(p.current.date.equals("2026-10-14"));rules.put("2026-10-13","2026-10-15");p=plan(rows,rules,"2026-10-14T08:30:00");check(p.current.name.equals("A"));p=plan(rows,rules,"2026-10-13T08:30:00");check(p.todayCount==0);check(p.next.name.equals("A"));
 rows.add(new CoursePlan.Course("2026-10-20","week2","","11:00","12:00"));p=plan(rows,rules,"2026-10-19T13:00:00");check(p.next.name.equals("week2"));rules.clear();rows.add(new CoursePlan.Course("2026-10-14","partial","","10:00",""));rows.add(new CoursePlan.Course("2026-10-14","untimed","","",""));p=plan(rows,rules,"2026-10-14T09:00:00");check(p.current==null);check(p.next.name.equals("partial"));check(p.untimed==2);check(p.next.location.isEmpty());
 CoursePlan.Plan utc=CoursePlan.calculate(rows,rules,at("2026-10-13T08:30:00"),ZoneId.of("UTC"));check(utc.current==null);check(utc.next.name.equals("A"));check(utc.boundary==Instant.parse("2026-10-13T08:00:00Z").toEpochMilli());
 System.out.println(count+" course projection and boundary checks passed");}
}
